"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["84041"],{27024(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.termo_exigido_formulario.entrada_malformada","status":422,"titulo":"A lista de termos ou um dos termos veio nulo"},"descricao":{"codigo":"uniplus.selecao.termo_exigido_formulario.entrada_malformada","requisitos":[],"oQueAconteceu":["O pedido `PUT .../formularios/{codigo}/termos` substitui por inteiro os termos de consentimento\\nque o formul\xe1rio do c\xf3digo exige. H\xe1 dois casos de entrada malformada, e a mensagem diz qual\\nocorreu:","- o campo `termos` veio com valor nulo: a lista \xe9 obrigat\xf3ria, e a lista vazia \xe9 o modo de remover\\n  todos os termos do formul\xe1rio;\\n- um dos itens da lista veio nulo: a mensagem diz que o termo veio nulo, e o campo de erro indica a\\n  posi\xe7\xe3o dele (`termos[i]`).","Quando o campo `termos` \xe9 omitido do corpo, o pedido nem chega a esta confer\xeancia: a omiss\xe3o \xe9\\nrecusada na leitura do corpo, antes do comando.","A lista nula \xe9 recusada logo depois das verifica\xe7\xf5es de que a edi\xe7\xe3o est\xe1 liberada (processo em\\nrascunho), como viola\xe7\xe3o \xfanica, antes de qualquer consulta\\nao cat\xe1logo de termos. O termo nulo \xe9 recusado junto com as demais viola\xe7\xf5es de forma dos outros\\ntermos, em `errors[]`; o termo nulo n\xe3o entra nas confer\xeancias seguintes, e nada foi alterado."],"comoResolver":["Envie `termos` como uma lista, vazia para remover os termos ou com um objeto por termo, sem itens\\nnulos, e repita o pedido. Se a resposta trouxer mais de uma viola\xe7\xe3o em `errors[]`, corrija todas antes\\nde reenviar."],"ondeAparece":["Grava\xe7\xe3o dos termos do formul\xe1rio"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Termo exigido formulario"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"fd5ea0ff72951399d2b2c1a4f29aeb3ea415db44"}}')}}]);